-- Table structure for table `email_delegation`
--

DROP TABLE IF EXISTS `email_delegation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `email_delegation` (
  `id` int NOT NULL AUTO_INCREMENT,
  `email_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `subject` varchar(255) DEFAULT NULL,
  `sender_address` varchar(255) DEFAULT NULL,
  `sender_name` varchar(255) DEFAULT NULL,
  `snippet` varchar(512) DEFAULT NULL,
  `to_recipients` longtext,
  `cc_recipients` longtext,
  `bcc_recipients` longtext,
  `assigned_user_id` int DEFAULT NULL,
  `status` varchar(10) NOT NULL,
  `delegated_at` datetime(6) DEFAULT NULL,
  `work_related` tinyint(1) NOT NULL DEFAULT '1',
  `email_category` varchar(50) DEFAULT NULL,
  `communication_type` varchar(50) DEFAULT NULL,
  `mip_names` varchar(555) DEFAULT NULL,
  `received_at` datetime(6) DEFAULT NULL,
  `body` longtext,
  `has_attachments` tinyint(1) NOT NULL DEFAULT '0',
  `eml_file_path` varchar(500) DEFAULT NULL,
  `is_fully_synced` tinyint(1) NOT NULL DEFAULT '0',
  `attachment` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email_id` (`email_id`),
  KEY `assigned_user_id` (`assigned_user_id`),
  CONSTRAINT `email_delegation_ibfk_1` FOREIGN KEY (`assigned_user_id`) REFERENCES `auth_user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4708 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

